    );
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Clock, PlayCircle, StopCircle, Loader2 } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { useToast } from '@/hooks/use-toast';

interface SankalpSession {
    id: string;
    duration: number; // in minutes
    startTime: Date;
}

export function SankalpSwitch() {
    const [isActive, setIsActive] = useState(false);
    const [duration, setDuration] = useState<number>(30);
    const [session, setSession] = useState<SankalpSession | null>(null);
    const [timeRemaining, setTimeRemaining] = useState<number>(0);
    const [loading, setLoading] = useState(false);
    const { user } = useAuth();
    const { toast } = useToast();

    // Timer countdown
    useEffect(() => {
        if (!isActive || !session) return;

        const timer = setInterval(() => {
            const now = new Date().getTime();
            const start = new Date(session.startTime).getTime();
            const elapsed = Math.floor((now - start) / 1000); // seconds
            const total = session.duration * 60; // convert to seconds
            const remaining = Math.max(0, total - elapsed);

            setTimeRemaining(remaining);

            // Auto-end when time is up
            if (remaining === 0) {
                handleEnd();
            }
        }, 1000);

        return () => clearInterval(timer);
    }, [isActive, session]);

    const handleStart = async () => {
        if (!user) {
            toast({
                title: 'Not authenticated',
                description: 'Please sign in first',
                variant: 'destructive',
            });
            return;
        }

        setLoading(true);

        try {
            const response = await fetch('/api/sankalp/session/start', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    studentId: user.uid,
                    targetDuration: duration,
                }),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'Failed to start session');
            }

            setSession({
                id: data.sessionId,
                duration,
                startTime: new Date(data.startTime),
            });
            setIsActive(true);
            setTimeRemaining(duration * 60);

            toast({
                title: 'SANKALP Loop Started',
                description: `${duration} minute session begun!`,
            });
        } catch (error: any) {
            const errorMsg = error.message || 'Something went wrong';
            // Map common errors to friendly messages without AI
            let friendlyMessage = 'Something went wrong. Please check your connection and try again.';
            if (errorMsg.includes('Active session already exists')) {
                friendlyMessage = 'You already have an active session. Please end it before starting a new one.';
            } else if (errorMsg.includes('Missing required fields')) {
                friendlyMessage = 'Please make sure you are signed in and have selected a duration.';
            }
            toast({
                title: 'Failed to start',
                description: friendlyMessage,
                variant: 'destructive',
            });
        } finally {
            setLoading(false);
        }
    };

    const handleEnd = async () => {
        if (!session) return;

        setLoading(true);

        try {
            const response = await fetch('/api/sankalp/session/end', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    sessionId: session.id,
                }),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'Failed to end session');
            }

            setIsActive(false);
            setSession(null);
            setTimeRemaining(0);

            toast({
                title: 'SANKALP Loop Completed',
                description: `Session ended. Duration: ${data.duration} minutes`,
            });
        } catch (error: any) {
            toast({
                title: 'Failed to end',
                description: error.message,
                variant: 'destructive',
            });
        } finally {
            setLoading(false);
        }
    };

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    return (
        <Card className="border-2 border-primary/20">
            <CardHeader>
                <div className="flex items-center justify-between">
                    <div>
                        <CardTitle className="flex items-center gap-2">
                            <Clock className="h-5 w-5 text-primary" />
                            SANKALP Loop
                        </CardTitle>
                        <CardDescription>
                            {isActive ? 'Session in progress' : 'Start a focused study session'}
                        </CardDescription>
                    </div>
                    <div
                        role="status"
                        className={`px-3 py-1 rounded-full text-sm font-medium ${isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'
                            }`}>
                        <span className="sr-only">Session status: </span>
                        {isActive ? 'Active' : 'Inactive'}
                    </div>
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                {!isActive ? (
                    <>
                        <div className="space-y-2">
                            <label htmlFor="session-duration" className="text-sm font-medium">Session Duration</label>
                            <Select
                                value={duration.toString()}
                                onValueChange={(val) => setDuration(parseInt(val))}
                            >
                                <SelectTrigger id="session-duration" aria-label="Select session duration">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="15">15 minutes</SelectItem>
                                    <SelectItem value="30">30 minutes</SelectItem>
                                    <SelectItem value="45">45 minutes</SelectItem>
                                    <SelectItem value="60">60 minutes</SelectItem>
                                    <SelectItem value="90">90 minutes</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <Button
                            onClick={handleStart}
                            className="w-full"
                            size="lg"
                            disabled={loading}
                        >
                            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            <PlayCircle className="mr-2 h-5 w-5" />
                            Start SANKALP Loop
                        </Button>
                    </>
                ) : (
                    <>
                        <div className="text-center py-6" role="timer" aria-live="off">
                            <div className="text-5xl font-mono font-bold text-primary">
                                {formatTime(timeRemaining)}
                            </div>
                            <p className="text-sm text-muted-foreground mt-2">
                                Time remaining
                            </p>
                        </div>
                        <Button
                            onClick={handleEnd}
                            variant="destructive"
                            className="w-full"
                            size="lg"
                            disabled={loading}
                        >
                            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            <StopCircle className="mr-2 h-5 w-5" />
                            End Session
                        </Button>
                    </>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useEffect, useRef, useMemo } from "react";
import { useStudent } from "@/hooks/useStudent";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Clock, Play, Pause, RotateCcw } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

type TimerMode = '25-min-focus' | '5-min-break' | '15-min-long-break';

const TIMER_DURATIONS = {
    '25-min-focus': 25 * 60,
    '5-min-break': 5 * 60,
    '15-min-long-break': 15 * 60,
};

// Psychological messages for different states
const MESSAGES = {
    focus_complete: [
        "Great job! Your brain needs a recharge. Take a breath and stretch.",
        "Focus session complete. Let your mind wander for a bit to consolidate learning.",
        "You've earned a break! Stepping away now will help you focus better next time.",
        "Well done! Rest is part of the work. Go grab some water."
    ],
    break_complete: [
        "Break is over. Let's get back into the flow!",
        "Refreshed? Time to conquer the next task.",
        "Ready to focus? Your goals are waiting.",
        "Time's up! Bring your attention back to your studies."
    ]
};

const getRandomMessage = (type: 'focus_complete' | 'break_complete') => {
    const messages = MESSAGES[type];
    return messages[Math.floor(Math.random() * messages.length)];
};

export function FocusTimer() {
    const { currentStudent } = useStudent();
    const { toast } = useToast();
    const [selectedTopic, setSelectedTopic] = useState("");
    const [timerMode, setTimerMode] = useState<TimerMode>('25-min-focus');
    const [timeLeft, setTimeLeft] = useState(TIMER_DURATIONS[timerMode]);
    const [isRunning, setIsRunning] = useState(false);
    const intervalRef = useRef<NodeJS.Timeout | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);

    // Get all topics from study materials
    const studyMaterials = currentStudent?.studyMaterials || [];
    const topics = useMemo(() => studyMaterials.map(m => m.topic), [studyMaterials]);

    // Format time as MM:SS
    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    const initAudio = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            if (!AudioContext) return;

            if (!audioContextRef.current) {
                audioContextRef.current = new AudioContext();
            }

            if (audioContextRef.current.state === 'suspended') {
                audioContextRef.current.resume();
            }
        } catch (error) {
            console.error("Error initializing audio:", error);
        }
    };

    const playNotificationSound = () => {
        try {
            if (!audioContextRef.current) return;

            const ctx = audioContextRef.current;
            const oscillator = ctx.createOscillator();
            const gainNode = ctx.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(ctx.destination);

            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(440, ctx.currentTime); // A4
            oscillator.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.1); // Jump to A5

            gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.00001, ctx.currentTime + 0.5);

            oscillator.start();
            oscillator.stop(ctx.currentTime + 0.5);
        } catch (error) {
            console.error("Error playing sound:", error);
        }
    };

    const handleTimerComplete = () => {
        setIsRunning(false);
        playNotificationSound();

        const isFocusMode = timerMode === '25-min-focus';
        const messageType = isFocusMode ? 'focus_complete' : 'break_complete';
        const title = isFocusMode ? "Focus Session Complete!" : "Break Over!";
        const message = getRandomMessage(messageType);

        // Toast notification
        toast({
            title: title,
            description: message,
            duration: 5000,
        });

        // Browser notification
        if (Notification.permission === "granted") {
            new Notification(title, {
                body: message,
                icon: "/favicon.ico" // Assuming favicon exists
            });
        }
    };

    // Timer logic
    useEffect(() => {
        if (isRunning && timeLeft > 0) {
            intervalRef.current = setInterval(() => {
                setTimeLeft(prev => {
                    if (prev <= 0) return 0;
                    return prev - 1;
                });
            }, 1000);
        }

        return () => {
            if (intervalRef.current) {
                clearInterval(intervalRef.current);
            }
        };
    }, [isRunning, timeLeft]);

    // Check for completion
    useEffect(() => {
        if (timeLeft === 0 && isRunning) {
            handleTimerComplete();
        }
    }, [timeLeft, isRunning]);

    const requestNotificationPermission = () => {
        if ("Notification" in window && Notification.permission === "default") {
            Notification.requestPermission();
        }
    };

    const handleStart = () => {
        if (!selectedTopic) {
            toast({
                title: "Topic Required",
                description: "Please select a topic before starting the timer.",
                variant: "destructive",
            });
            return;
        }
        initAudio();
        requestNotificationPermission();
        setIsRunning(true);
    };

    const handlePause = () => {
        setIsRunning(false);
    };

    const handleReset = () => {
        setIsRunning(false);
        setTimeLeft(TIMER_DURATIONS[timerMode]);
    };

    const handleModeChange = (mode: TimerMode) => {
        setTimerMode(mode);
        setTimeLeft(TIMER_DURATIONS[mode]);
        setIsRunning(false);
    };

    const progress = ((TIMER_DURATIONS[timerMode] - timeLeft) / TIMER_DURATIONS[timerMode]) * 100;

    return (
        <Card className="max-w-2xl mx-auto">
            <CardHeader>
                <div className="flex items-center justify-center gap-2">
                    <Clock className="h-5 w-5" />
                    <CardTitle>Pomodoro</CardTitle>
                </div>
            </CardHeader>
            <CardContent className="space-y-6">
                {/* Topic Selection */}
                <div className="space-y-2">
                    <Label htmlFor="study-topic">
                        What do you want to study?
                    </Label>
                    <Select value={selectedTopic} onValueChange={setSelectedTopic}>
                        <SelectTrigger id="study-topic">
                            <SelectValue placeholder="Select a topic" />
                        </SelectTrigger>
                        <SelectContent>
                            {topics.length > 0 ? (
                                topics.map(topic => (
                                    <SelectItem key={topic} value={topic}>
                                        {topic}
                                    </SelectItem>
                                ))
                            ) : (
                                <SelectItem value="none" disabled>
                                    No topics available
                                </SelectItem>
                            )}
                        </SelectContent>
                    </Select>
                </div>

                {/* Session Type Selector */}
                <div className="flex gap-2 justify-center">
                    <Button
                        variant={timerMode === '25-min-focus' ? 'default' : 'outline'}
                        onClick={() => handleModeChange('25-min-focus')}
                        size="sm"
                    >
                        25-min Focus
                    </Button>
                    <Button
                        variant={timerMode === '5-min-break' ? 'default' : 'outline'}
                        onClick={() => handleModeChange('5-min-break')}
                        size="sm"
                    >
                        5-min Break
                    </Button>
                    <Button
                        variant={timerMode === '15-min-long-break' ? 'default' : 'outline'}
                        onClick={() => handleModeChange('15-min-long-break')}
                        size="sm"
                    >
                        15-min Long Break
                    </Button>
                </div>

                {/* Timer Display */}
                <div className="text-center space-y-4">
                    <div
                        className="text-7xl font-bold tabular-nums text-primary"
                        role="timer"
                        aria-label="Time remaining"
                    >
                        {formatTime(timeLeft)}
                    </div>

                    {/* Progress Bar */}
                    <Progress value={progress} className="h-2" />

                    {/* Control Buttons */}
                    <div className="flex gap-4 justify-center pt-4">
                        {!isRunning ? (
                            <Button onClick={handleStart} size="lg" className="w-32">
                                <Play className="h-4 w-4 mr-2" />
                                Start
                            </Button>
                        ) : (
                            <Button onClick={handlePause} size="lg" variant="secondary" className="w-32">
                                <Pause className="h-4 w-4 mr-2" />
                                Pause
                            </Button>
                        )}
                        <Button onClick={handleReset} size="lg" variant="outline">
                            <RotateCcw className="h-4 w-4 mr-2" />
                            Reset
                        </Button>
                    </div>
                </div>

                {/* Current Task Display */}
                {selectedTopic && (
                    <div className="text-center p-4 bg-muted rounded-lg">
                        <p className="text-sm text-muted-foreground">Currently studying</p>
                        <p className="font-medium">{selectedTopic}</p>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { useStudent } from "@/hooks/useStudent";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Lightbulb, BookCheck, Calendar, AlertTriangle, Loader2 } from "lucide-react";
import { getRevisionPlan } from "@/app/(main)/planner/actions";
import type { SmartRevisionPlannerOutput } from "@/ai/flows/smart-revision-planner";

export function ScheduleView() {
    const { currentStudent } = useStudent();
    const [plan, setPlan] = useState<SmartRevisionPlannerOutput | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const studyMaterials = currentStudent?.studyMaterials || [];

    // Get upcoming deadlines (Due or upcoming soon)
    const upcomingDeadlines = useMemo(() => studyMaterials
        .filter(m => m.status === 'Due' || m.status === 'Upcoming')
        .sort((a, b) => new Date(a.nextReview).getTime() - new Date(b.nextReview).getTime()), [studyMaterials]);

    const handleGeneratePlan = async () => {
        setLoading(true);
        setError(null);
        setPlan(null);
        const result = await getRevisionPlan();
        if (result) {
            setPlan(result);
        } else {
            setError("Failed to generate a revision plan. Please try again.");
        }
        setLoading(false);
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Left Side - AI Generated Plan */}
            <div className="lg:col-span-2 space-y-4">
                <Card>
                    <CardHeader>
                        <CardTitle>AI Generated Plan</CardTitle>
                        <CardDescription>
                            Today's AI Suggestions - Click the button below to generate a personalized study plan for today.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Button onClick={handleGeneratePlan} disabled={loading}>
                            {loading ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Generating...
                                </>
                            ) : (
                                "Generate Today's Plan"
                            )}
                        </Button>
                    </CardContent>
                </Card>

                {error && (
                    <Card className="border-destructive">
                        <CardHeader className="flex flex-row items-center gap-4">
                            <AlertTriangle className="h-8 w-8 text-destructive" />
                            <div>
                                <CardTitle className="text-destructive">An Error Occurred</CardTitle>
                                <CardDescription>{error}</CardDescription>
                            </div>
                        </CardHeader>
                    </Card>
                )}

                {plan && plan.revisionList.length > 0 && (
                    <div className="space-y-4">
                        {plan.revisionList.map((task, index) => (
                            <Card key={index} className="hover:border-primary transition-colors">
                                <CardHeader className="flex flex-row items-start justify-between">
                                    <div>
                                        <CardTitle>{task.topic}</CardTitle>
                                        <CardDescription className="flex items-center gap-2 mt-1">
                                            <Lightbulb className="w-4 h-4 text-amber-500" />
                                            <span>{task.reason}</span>
                                        </CardDescription>
                                    </div>
                                    <Button size="sm" variant="outline">
                                        <BookCheck className="mr-2 h-4 w-4" />
                                        Revise Now
                                    </Button>
                                </CardHeader>
                            </Card>
                        ))}
                    </div>
                )}

                {plan && plan.revisionList.length === 0 && (
                    <Card>
                        <CardHeader>
                            <CardTitle>All Caught Up!</CardTitle>
                            <CardDescription>
                                No priority revisions for today. Feel free to explore new topics!
                            </CardDescription>
                        </CardHeader>
                    </Card>
                )}
            </div>

            {/* Right Side - Upcoming Deadlines */}
            <div>
                <Card>
                    <CardHeader>
                        <CardTitle>Upcoming Deadlines</CardTitle>
                        <CardDescription>
                            Materials that need review soon
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        {upcomingDeadlines.length === 0 ? (
                            <div className="text-center py-8">
                                <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                                <p className="text-muted-foreground text-sm">
                                    No upcoming deadlines
                                </p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {upcomingDeadlines.map(material => {
                                    const daysUntil = Math.ceil(
                                        (new Date(material.nextReview).getTime() - Date.now()) / (1000 * 60 * 60 * 24)
                                    );
                                    const isOverdue = daysUntil < 0;

                                    return (
                                        <div
                                            key={material.id}
                                            className="p-4 rounded-lg border hover:border-primary transition-colors"
                                        >
                                            <div className="flex items-start justify-between mb-2">
                                                <div>
                                                    <div className="font-medium">{material.topic}</div>
                                                    <div className="text-sm text-muted-foreground">
                                                        {material.subject}
                                                    </div>
                                                </div>
                                                <Badge variant={isOverdue ? "destructive" : "default"}>
                                                    {isOverdue ? "Overdue" : material.status}
                                                </Badge>
                                            </div>
                                            <div className="text-sm text-muted-foreground">
                                                {isOverdue
                                                    ? `${Math.abs(daysUntil)} days overdue`
                                                    : daysUntil === 0
                                                        ? "Due today"
                                                        : `Due in ${daysUntil} ${daysUntil === 1 ? "day" : "days"}`}
                                            </div>
                                            <div className="text-xs text-muted-foreground mt-1">
                                                {new Date(material.nextReview).toLocaleDateString()}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

"use client";

import { useState, useMemo } from "react";
import { useStudent } from "@/hooks/useStudent";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { BookOpen, Search, Filter, ExternalLink } from "lucide-react";
import type { StudyMaterial } from "@/data/docsData";

export function StudyLibrary() {
    const { currentStudent } = useStudent();
    const [searchTerm, setSearchTerm] = useState("");
    const [filterSubject, setFilterSubject] = useState("all");
    const [selectedMaterial, setSelectedMaterial] = useState<StudyMaterial | null>(null);

    // Get study materials from current student
    const studyMaterials = currentStudent?.studyMaterials || [];

    // Get unique subjects
    const subjects = useMemo(() => Array.from(new Set(studyMaterials.map(m => m.subject))), [studyMaterials]);

    // Filter materials
    const filteredMaterials = useMemo(() => studyMaterials.filter(material => {
        const matchesSearch = material.topic.toLowerCase().includes(searchTerm.toLowerCase()) ||
            material.subject.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesFilter = filterSubject === "all" || material.subject === filterSubject;
        return matchesSearch && matchesFilter;
    }), [studyMaterials, searchTerm, filterSubject]);

    // Status badge styles
    const getStatusVariant = (status: string) => {
        switch (status) {
            case 'Due':
                return 'destructive';
            case 'Upcoming':
                return 'default';
            case 'Reviewed':
                return 'secondary';
            default:
                return 'outline';
        }
    };

    if (!currentStudent) {
        return <div>Loading...</div>;
    }

    return (
        <div className="space-y-6">
            <Card>
                <CardHeader>
                    <CardTitle>Your Study Library</CardTitle>
                    <CardDescription>
                        All your study materials in one place. Filter and search to manage your knowledge base.
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="flex flex-col sm:flex-row gap-4 mb-6">
                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                            <Input
                                placeholder="Search topics..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-10"
                            />
                        </div>
                        <Select value={filterSubject} onValueChange={setFilterSubject}>
                            <SelectTrigger className="w-full sm:w-[200px]">
                                <Filter className="h-4 w-4 mr-2" />
                                <SelectValue placeholder="Filter by subject" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Subjects</SelectItem>
                                {subjects.map(subject => (
                                    <SelectItem key={subject} value={subject}>
                                        {subject}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    {filteredMaterials.length === 0 ? (
                        <div className="text-center py-12">
                            <BookOpen className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                            <h3 className="text-lg font-semibold mb-2">No study materials found</h3>
                            <p className="text-muted-foreground">
                                {searchTerm || filterSubject !== "all"
                                    ? "Try adjusting your filters"
                                    : "Add your first study material to get started"}
                            </p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {filteredMaterials.map(material => (
                                <Card key={material.id} className="hover:border-primary transition-colors">
                                    <CardHeader>
                                        <div className="flex items-start justify-between">
                                            <div className="flex-1">
                                                <div className="text-sm text-muted-foreground mb-1">
                                                    {material.subject}
                                                </div>
                                                <CardTitle className="text-lg">{material.topic}</CardTitle>
                                                {material.chapter && (
                                                    <p className="text-sm text-muted-foreground mt-1">
                                                        {material.chapter}
                                                    </p>
                                                )}
                                            </div>
                                            <Badge variant={getStatusVariant(material.status)}>
                                                {material.status}
                                            </Badge>
                                        </div>
                                    </CardHeader>
                                    <CardContent>
                                        <div className="space-y-2">
                                            <div className="text-sm">
                                                <span className="text-muted-foreground">Next Review:</span>{" "}
                                                <span className="font-medium">
                                                    {new Date(material.nextReview).toLocaleDateString()}
                                                </span>
                                            </div>
                                            {material.lastReviewed && (
                                                <div className="text-sm">
                                                    <span className="text-muted-foreground">Last Reviewed:</span>{" "}
                                                    <span className="font-medium">
                                                        {new Date(material.lastReviewed).toLocaleDateString()}
                                                    </span>
                                                </div>
                                            )}
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                className="w-full mt-4"
                                                onClick={() => setSelectedMaterial(material)}
                                            >
                                                View Details
                                            </Button>
                                        </div>
                                    </CardContent>
                                </Card>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Detail Dialog */}
            <Dialog open={!!selectedMaterial} onOpenChange={(open: boolean) => !open && setSelectedMaterial(null)}>
                <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
                    {selectedMaterial && (
                        <>
                            <DialogHeader>
                                <div className="flex items-center gap-2 mb-1">
                                    <Badge variant={getStatusVariant(selectedMaterial.status)}>
                                        {selectedMaterial.status}
                                    </Badge>
                                    <span className="text-sm text-muted-foreground">{selectedMaterial.subject}</span>
                                </div>
                                <DialogTitle className="text-xl">{selectedMaterial.topic}</DialogTitle>
                                {selectedMaterial.chapter && (
                                    <DialogDescription>{selectedMaterial.chapter}</DialogDescription>
                                )}
                            </DialogHeader>

                            <div className="space-y-4 mt-4">
                                {/* Notes */}
                                {selectedMaterial.detailedNotes && (
                                    <div>
                                        <h4 className="text-sm font-semibold mb-2">Notes</h4>
                                        <div className="bg-muted/50 rounded-lg p-4 text-sm whitespace-pre-wrap">
                                            {selectedMaterial.detailedNotes}
                                        </div>
                                    </div>
                                )}

                                {/* Review Info */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-muted/30 rounded-lg p-3">
                                        <div className="text-xs text-muted-foreground mb-1">Next Review</div>
                                        <div className="text-sm font-medium">
                                            {new Date(selectedMaterial.nextReview).toLocaleDateString()}
                                        </div>
                                    </div>
                                    {selectedMaterial.lastReviewed && (
                                        <div className="bg-muted/30 rounded-lg p-3">
                                            <div className="text-xs text-muted-foreground mb-1">Last Reviewed</div>
                                            <div className="text-sm font-medium">
                                                {new Date(selectedMaterial.lastReviewed).toLocaleDateString()}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {/* Reference Links */}
                                {selectedMaterial.referenceLinks && selectedMaterial.referenceLinks.length > 0 && (
                                    <div>
                                        <h4 className="text-sm font-semibold mb-2">Reference Links</h4>
                                        <div className="space-y-2">
                                            {selectedMaterial.referenceLinks.map((link, i) => (
                                                <a
                                                    key={i}
                                                    href={link}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="flex items-center gap-2 text-sm text-primary hover:underline"
                                                >
                                                    <ExternalLink className="h-3 w-3" />
                                                    {link}
                                                </a>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}
